\coordinate (B) at ($(Bp)+(0,\hB)$);
\coordinate (C) at ($(Cp)+(0,\hC)$);

\draw[dashed] (Ap) -- (A);
\draw[thick] (Bp) -- (B);
\draw[thick] (Cp) -- (C);

% --- triangle ABC in space ---
\draw[thick] (A) -- (B) -- (C) -- cycle;

% --- some auxiliary dashed lines on the plane (to mimic the sketch) ---
\draw[dashed] (Ap) -- (Bp);
\draw[dashed] (Ap) -- (Cp);

% labels of A,B,C
\node[above] at (A) {$A$};
