\coordinate (Q) at ({sqrt(2)},{sqrt(2)});

\node[below left] at (O) {$O$};
\fill (Q) circle (1.2pt);
\node[right] at ($(Q)+(0.1,0.1)$) {$Q$};

% circle C: x^2 + y^2 = 1
